	// aqui podemos adicionar mais regras de rotação de proxy para diferentes urls e cabeçalhos da solicitação http.

	// escolha um dos servidores remotos aleatoriamente para proxies diretos.  
	let servers = [    { host: 'proxy 1', port: 8080 },    { host: 'proxy 2', port: 8090 },    { host: 'proxy 3', port: 9090 }];  

	let randomserveridx = math.floor(math.random() * servers.length);  

	let options = {    method: req.method,    headers: req.headers,    url: req.url,    target: `http://${servers[randomserveridx].host}:${servers[randomserveridx].port}` };  

	console.log(`proxy utilizado : ${options['target']}`);  

	let outgoingreq = http.request(options);  

