conn.waitformessage = async function (chatid, senderid, quotedmessage, checkmessage = () => true/* função para checar se a msg tá do jeito que você quer*/, timeout = 1000 * 60 /* 1 minuto */, callback = () => {}) {
    return new promise(async (resolve, reject) => {
      try {
        global.timeouterror = global.timeouterror || class timeouterror extends error {constructor(msg){super(msg)}};
        var status;
        settimeout(() => {
          if(status) return;
          status = true;
          reject(new timeouterror('o tempo para receber a mensagem expirou'));
        }, timeout)
        const botnumber = await this.user.id.split(':')[0]+'@s.whatsapp.net';
        this.ev.on('messages.upsert', async ({messages: [msg]}) => {
          if(status) return;
          var type = require('@adiwajshing/baileys').getcontenttype(msg.message);
          msg.quoted = !!(msg.message[type]?.contextinfo && msg.message[type]?.contextinfo?.quotedmessage) ? {...msg.message[type].contextinfo?.quotedmessage, id: msg.message[type].contextinfo?.stanzaid, participant: msg.message[type].contextinfo?.participant, fromme: msg.message[type].contextinfo?.participant == botnumber } : null;
          msg.from = msg.key.remotejid;
          msg.isgroup = msg.from.endswith('@g.us');
          msg.body = msg.message?.conversation || msg.message?.viewoncemessagev2?.message?.imagemessage?.caption || msg.message?.viewoncemessagev2?.message?.videomessage?.caption || msg.message?.imagemessage?.caption || msg.message?.videomessage?.caption || msg.message?.extendedtextmessage?.text || msg.message?.viewoncemessage?.message?.videomessage?.caption || msg.message?.viewoncemessage?.message?.imagemessage?.caption || msg.message?.documentwithcaptionmessage?.message?.documentmessage?.caption || msg.message?.buttonsmessage?.imagemessage?.caption || msg.message?.buttonsresponsemessage?.selectedbuttonid || msg.message?.listresponsemessage?.singleselectreply?.selectedrowid || msg.message?.templatebuttonreplymessage?.selectedid || msg?.text || '';
          msg.sender = msg.isgroup ? msg.key.participant.includes(':') ? msg.key.participant.split(':')[0] +'@s.whatsapp.net': msg.key.participant : msg.key.remotejid;
          msg.timeouterror = timeouterror
          if(msg.sender === senderid && msg.from === chatid && await checkmessage(msg) && (!quotedmessage || quotedmessage?.key?.id == msg?.quoted?.id)) {
            status = true;
            await this.sendpresenceupdate('composing', msg.from).catch();
            await callback(msg);
            resolve(object.assign({msg}, msg));
          };
        });
      } catch (e) {
        reject(e);
      }
    });
  }

