import { decryptpollvote } from "@whiskeysockets/baileys";
import digestsync from "crypto-digest-sync";

const pollcreation: proto.iwebmessageinfo;
const pollupdate: proto.iwebmessageinfo;
const voterjid = pollupdate.key.fromme ? client.id : pollupdate.key.participant || pollupdate.key.remotejid;
const savedvotes: { [id: string]: string[] } = {};

const poll = decryptpollvote(pollupdate.message.pollupdatemessage.vote, {
  pollcreatorjid: pollcreation.key.fromme ? client.id : pollcreation.key.participant || pollcreation.key.remotejid,
  pollmsgid: pollupdate.message.pollupdatemessage.pollcreationmessagekey.id,
  pollenckey: pollcreation.message.messagecontextinfo.messagesecret,
  voterjid,
});

const votesalias: { [name: string]: string } = {};
const hashvotes: string[] = poll.selectedoptions.map((opt) => buffer.from(opt).tostring("hex").touppercase()).sort();
const oldvotes: string[] = savedvotes[voterjid].sort();
const nowvotes: string[] = [];

// get hash votes values
for (const opt of pollcreation.message.pollcreationmessage.options) {
  const hash = buffer.from(digestsync("sha-256", new textencoder().encode(buffer.from(opt.optionname).tostring())))
    .tostring("hex")
    .touppercase();

  votesalias[opt.optionname] = opt.optionname;

  if (hashvotes.includes(hash)) {
    nowvotes.push(opt.optionname);
  }
}

let vote: string | null = null;
let action: "add" | "remove" = "add";

const avaiblevotes = object.keys(votesalias);

for (const name of avaiblevotes) {
  if (nowvotes.length > oldvotes.length) {
    if (oldvotes.includes(name) || !nowvotes.includes(name)) continue;

    action = "add";
    vote = votesalias[name];

    break;
  } else {
    if (nowvotes.includes(name) || !oldvotes.includes(name)) continue;

    action = "remove";
    vote = votesalias[name];

    break;
  }
}
